import json, random, subprocess, sys, time

def make(seed, mode):
    rng = random.Random(seed)
    nflows = 22
    if mode == 'same':
        nodes = ['a','b']
        caps = {'a': 11, 'b': 11}
        paths = [['a','b'] for _ in range(nflows)]
    elif mode == 'chain':
        nodes = ['n%d'%i for i in range(22)]
        caps = {n: 1 for n in nodes}
        paths = [[nodes[i], nodes[(i+1)%22]] for i in range(22)]
    elif mode == 'wide':
        nodes = ['n%d'%i for i in range(8)]
        caps = {n: 512 for n in nodes}
        paths = [rng.sample(nodes, 3) for _ in range(nflows)]
    elif mode == 'tight':
        nodes = ['n%d'%i for i in range(4)]
        caps = {n: 5 for n in nodes}
        paths = [rng.sample(nodes, rng.randint(2,3)) for _ in range(nflows)]
    elif mode == 'equal':
        nodes = ['n%d'%i for i in range(3)]
        caps = {n: 3 for n in nodes}
        paths = [rng.sample(nodes, 2) for _ in range(nflows)]
    flows=[]
    for i in range(nflows):
        fid='f%02d'%i
        kinds='QTKKKKKKKD'
        flows.append(dict(id=fid,path=paths[i],template=('%02x'%i)*10,kinds=kinds))
    offers={f['id']:[dict(header=f['template'],count=1000)] for f in flows}
    pinned=[]
    return dict(mode='plan',capacities=caps,flows=flows,warmup=0,pinned=pinned,offers=offers)

for mode in ['same','chain','wide','tight','equal']:
    worst = 0
    for seed in range(5):
        req = make(seed, mode)
        t0=time.time()
        out = subprocess.run([sys.executable,'-I','-B','/workspace/submission/main.py'],
                             input=json.dumps(req)+'\n', text=True, capture_output=True)
        dt=time.time()-t0
        worst=max(worst,dt)
        res=out.stdout.strip()[:60]
    print(mode, 'worst %.2fs' % worst, res)
